async page => {
 await page.goto('http://127.0.0.1:3000');
 await page.waitForFunction(()=>document.querySelector('video').readyState >= 1);
 const track=await(await page.request.get('http://127.0.0.1:3000/research/demo-captions.json')).json();
 const apple=track.cues.find(c=>c.original_text==='[APPLE THUDS]'); const mid=(apple.start_s+apple.end_s)/2;
 await page.locator('.cue-row').nth(track.cues.indexOf(apple)).click();
 await page.getByRole('button',{name:'Rich',exact:true}).click();
 const preview=page.getByRole('button',{name:'Preview this cue in the video',exact:true});
 await preview.click(); await page.locator('.caption-preview-notice').waitFor({state:'visible'});
 await page.waitForFunction(s=>Math.abs(document.querySelector('video').currentTime-s)<.02,mid);
 await page.locator('#timeline').focus(); await page.keyboard.press('ArrowRight');
 await page.locator('.caption-preview-notice').waitFor({state:'hidden',timeout:1500});
 await page.waitForFunction(s=>document.querySelector('video').currentTime>s+.01,mid,{timeout:2000});
 const keyboardTime=await page.locator('video').evaluate(el=>el.currentTime);
 await preview.click();await page.locator('.caption-preview-notice').waitFor({state:'visible'});
 await page.locator('#timeline').scrollIntoViewIfNeeded(); const box=await page.locator('#timeline').boundingBox();
 await page.mouse.click(box.x+box.width*.7,box.y+box.height/2);
 await page.locator('.caption-preview-notice').waitFor({state:'hidden',timeout:1500});
 await page.waitForFunction(()=>document.querySelector('video').currentTime>400,{},{timeout:2000});
 return {keyboardTime,pointerTime:await page.locator('video').evaluate(el=>el.currentTime),keyboardCancel:true,pointerCancel:true};
}
